<template><header class="app-header"><div class="context"><span>{{ meta[0] }}</span><small>{{ meta[1] }}</small></div><div class="actions"><button id="bell-btn" type="button" aria-label="通知" @click.stop="toggle"><el-icon><Bell /></el-icon><i v-if="count">{{ count }}</i></button><button type="button" aria-label="帮助中心"><el-icon><QuestionFilled /></el-icon></button></div></header><Teleport to="body"><div v-if="show" id="notification-dropdown" class="notification-dropdown" @click.stop><NotificationList @close="show=false" /></div></Teleport></template>
<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue';import {useRoute} from 'vue-router';import {Bell,QuestionFilled} from '@element-plus/icons-vue';import {useNotificationStore} from '../../stores/notificationStore';import NotificationList from './NotificationList.vue'
const route=useRoute(),store=useNotificationStore(),show=ref(false);const routes={'/':['工作台','今日教学概览'],'/grade':['批改中心','统一处理作业与重练任务'],'/weekly-report':['学习诊断','从数据发现问题并安排下一步'],'/wrongbook':['错题中心','沉淀、筛选与追踪长期错题'],'/worksheets':['练习册管理','管理练习册内容与答案状态']};const meta=computed(()=>Object.entries(routes).find(([path])=>path==='/'?route.path==='/':route.path.startsWith(path))?.[1]||['教师工作台','敏学教学工作系统']);const count=computed(()=>store.totalCount>99?'99+':store.totalCount||'');const toggle=()=>{show.value=!show.value;if(show.value)store.fetchSummary()};const close=e=>{if(!e.target.closest('#notification-dropdown')&&!e.target.closest('#bell-btn'))show.value=false};onMounted(()=>{store.startPolling();document.addEventListener('click',close)});onUnmounted(()=>{store.stopPolling();document.removeEventListener('click',close)})
</script>
<style scoped>.app-header{display:flex;align-items:center;justify-content:space-between;height:var(--wb-header-height);flex:0 0 var(--wb-header-height);box-sizing:border-box;padding:0 28px;background:rgba(255,255,255,.94);border-bottom:1px solid var(--wb-border);backdrop-filter:blur(16px)}.context{display:flex;align-items:baseline;gap:10px}.context span{color:var(--wb-text);font-size:14px;font-weight:650}.context small{color:var(--wb-text-tertiary);font-size:12px}.actions{display:flex;gap:4px}.actions button{position:relative;display:grid;width:34px;height:34px;place-items:center;color:var(--wb-text-secondary);background:transparent;border:0;border-radius:8px;cursor:pointer}.actions button:hover{color:var(--wb-text);background:var(--wb-bg-hover)}.actions i{position:absolute;top:1px;right:0;min-width:15px;height:15px;padding:0 3px;box-sizing:border-box;color:#fff;font:600 9px/15px sans-serif;background:var(--wb-danger);border-radius:8px}.notification-dropdown{position:fixed;top:54px;right:22px;z-index:2100;overflow:hidden;background:#fff;border:1px solid var(--wb-border);border-radius:10px;box-shadow:var(--wb-shadow-lg)}</style>
